sys_ui_action.script:
function runCopyPreviousWeek() {
    var ga = new GlideAjax('x_783736_time_tr_0.TimeTrackerUtils');
    ga.addParam('sysparm_name', 'copyPreviousWeek');

    ga.getXMLAnswer(function(response) {
        if (!response) {
            return;
        }
        var res = JSON.parse(response);
        if (res.count > 0) {
            alert('Copied ' + res.count + ' time entr' + (res.count === 1 ? 'y' : 'ies') + ' from last week (' + res.start + ' to ' + res.end + ').');
            // Reload the list so the newly copied rows appear immediately
                    if (res.count > 0) {
            alert('Copied ' + res.count + ' time entr' + (res.count === 1 ? 'y' : 'ies') + ' from last week (' + res.start + ' to ' + res.end + ').');

            // Refresh the list directly in Next Experience / Core UI
            if (typeof g_list !== 'undefined' && g_list) {
                g_list.refresh();
            } else {
                window.self.location.replace(window.self.location.pathname + window.self.location.search);
            }
        }

        } else {
            alert('No time entries found from last week (' + res.start + ' to ' + res.end + ').');
        }
    });
}
